<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
$page=(string)($_GET['page']??'dashboard');
$public=['login'];
if(!in_array($page,$public,true))require_login();
$error=null;
try {
 if($_SERVER['REQUEST_METHOD']==='POST') {
  check_csrf();$action=(string)($_POST['action']??'');
  if($action==='login') {
   $username=strtolower(trim((string)($_POST['username']??'')));$q=db()->prepare('SELECT * FROM users WHERE username=?');$q->execute([$username]);$u=$q->fetch();
   if(!$u||!password_verify((string)($_POST['password']??''),$u['password_hash'])){usleep(250000);throw new RuntimeException('Incorrect username or password.');}
   session_regenerate_id(true);$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'role'=>$u['role']];redirect('dashboard');
  }
  if($action==='logout'){$_SESSION=[];session_regenerate_id(true);redirect('login');}
  require_login();
  if($action==='save_product'){
   require_admin();$id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$sku=trim((string)($_POST['sku']??''));$cat=(int)($_POST['category_id']??0);$price=amount($_POST['price']??'');$cost=amount($_POST['cost']??'0');$low=(int)($_POST['low_stock']??5);
   if($name===''||$sku===''||$low<0||$low>10000000)throw new RuntimeException('Check product details.');
   $image=null;
   if(isset($_FILES['product_image']) && $_FILES['product_image']['error']!==UPLOAD_ERR_NO_FILE){
    $file=$_FILES['product_image'];
    if($file['error']!==UPLOAD_ERR_OK||$file['size']>2097152||$file['size']<1)throw new RuntimeException('Product image must be 2 MB or smaller.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);
    $ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;
    if(!$ext||!getimagesize($file['tmp_name']))throw new RuntimeException('Upload a valid PNG, JPG or WebP product image.');
    $image='uploads/'.bin2hex(random_bytes(16)).'.'.$ext;
    if(!move_uploaded_file($file['tmp_name'],__DIR__.'/'.$image))throw new RuntimeException('Product image upload failed.');
   }
   if($id>0){$q=db()->prepare('UPDATE products SET name=?,sku=?,category_id=?,price=?,cost=?,low_stock=? WHERE id=?');$q->execute([$name,$sku,$cat?:null,dec($price),dec($cost),$low,$id]);if($image!==null){$q=db()->prepare('UPDATE products SET image_path=? WHERE id=?');$q->execute([$image,$id]);}}
   else{$q=db()->prepare('INSERT INTO products(name,sku,category_id,price,cost,low_stock,image_path) VALUES(?,?,?,?,?,?,?)');$q->execute([$name,$sku,$cat?:null,dec($price),dec($cost),$low,$image]);}
   flash('Product saved.');redirect('inventory');
  }
  if($action==='stock'){
   require_admin();$id=(int)($_POST['id']??0);$qty=filter_var($_POST['qty']??null,FILTER_VALIDATE_INT);$reason=trim((string)($_POST['reason']??'Stock adjustment'));
   if(!$id||$qty===false||$qty===0||abs($qty)>10000000||$reason==='')throw new RuntimeException('Enter a valid stock change.');
   $pdo=db();$pdo->beginTransaction();
   try{$q=$pdo->prepare('UPDATE products SET stock=stock+? WHERE id=? AND stock+?>=0');$q->execute([$qty,$id,$qty]);if($q->rowCount()!==1)throw new RuntimeException('Stock adjustment failed or insufficient stock.');$q=$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,change_qty,reason) VALUES(?,?,?,?)');$q->execute([$id,$_SESSION['user']['id'],$qty,$reason]);$pdo->commit();}
   catch(Throwable $ex){$pdo->rollBack();throw $ex;}flash('Stock updated.');redirect('inventory');
  }
  if($action==='category'){
   require_admin();$name=trim((string)($_POST['name']??''));if($name==='')throw new RuntimeException('Category name required.');$q=db()->prepare('INSERT INTO categories(name) VALUES(?)');$q->execute([$name]);flash('Category added.');redirect('inventory');
  }
  if($action==='toggle_product'){
   require_admin();$q=db()->prepare('UPDATE products SET active=NOT active WHERE id=?');$q->execute([(int)($_POST['id']??0)]);flash('Product status updated.');redirect('inventory');
  }
  if($action==='checkout'){
   $cart=json_decode((string)($_POST['cart']??''),true,32,JSON_THROW_ON_ERROR);if(!is_array($cart)||count($cart)<1||count($cart)>100)throw new RuntimeException('Your cart is empty or too large.');
   $discount=amount($_POST['discount']??'0');$paid=amount($_POST['paid']??'0');$payment=(string)($_POST['payment']??'cash');if(!in_array($payment,['cash','card','gcash','other'],true))throw new RuntimeException('Invalid payment method.');
   $items=[];foreach($cart as $entry){if(!is_array($entry))throw new RuntimeException('Invalid item.');$id=filter_var($entry['id']??null,FILTER_VALIDATE_INT);$qty=filter_var($entry['qty']??null,FILTER_VALIDATE_INT);if(!$id||!$qty||$qty<1||$qty>10000||isset($items[$id]))throw new RuntimeException('Invalid cart quantities.');$items[$id]=$qty;}
   $pdo=db();$pdo->beginTransaction();
   try{$subtotal=0;$rows=[];$q=$pdo->prepare('SELECT id,name,price,stock FROM products WHERE id=? AND active=1 FOR UPDATE');
    foreach($items as $id=>$qty){$q->execute([$id]);$p=$q->fetch();if(!$p||$p['stock']<$qty)throw new RuntimeException('Insufficient stock for one or more products.');$unit=amount($p['price']);$line=$unit*$qty;$subtotal+=$line;$rows[]=['id'=>$id,'name'=>$p['name'],'qty'=>$qty,'unit'=>$unit,'line'=>$line];}
    if($discount>$subtotal)throw new RuntimeException('Discount exceeds subtotal.');$total=$subtotal-$discount;if($paid<$total)throw new RuntimeException('Amount paid is insufficient.');
    $s=$pdo->prepare('INSERT INTO sales(user_id,subtotal,discount,total,amount_paid,change_due,payment_method) VALUES(?,?,?,?,?,?,?)');$s->execute([$_SESSION['user']['id'],dec($subtotal),dec($discount),dec($total),dec($paid),dec($paid-$total),$payment]);$saleId=(int)$pdo->lastInsertId();
    $i=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?)');$u=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');$m=$pdo->prepare('INSERT INTO stock_movements(product_id,user_id,change_qty,reason) VALUES(?,?,?,?)');
    foreach($rows as $r){$i->execute([$saleId,$r['id'],$r['name'],$r['qty'],dec($r['unit']),dec($r['line'])]);$u->execute([$r['qty'],$r['id']]);$m->execute([$r['id'],$_SESSION['user']['id'],-$r['qty'],'Sale #'.$saleId]);}
    $pdo->commit();redirect('receipt&id='.$saleId);
   }catch(Throwable $ex){$pdo->rollBack();throw $ex;}
  }
  if($action==='save_settings'){
   require_admin();$store=trim((string)($_POST['store_name']??''));$color=(string)($_POST['primary_color']??'#2563eb');if($store===''||mb_strlen($store)>100||!preg_match('/^#[a-fA-F0-9]{6}$/',$color))throw new RuntimeException('Invalid store name or color.');
   $logo=setting('logo_path');
   if(!empty($_FILES['logo']['name'])){
    if($_FILES['logo']['error']!==UPLOAD_ERR_OK||$_FILES['logo']['size']>2097152)throw new RuntimeException('Logo must be 2 MB or smaller.');
    $mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['logo']['tmp_name']);$ext=['image/png'=>'png','image/jpeg'=>'jpg','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new RuntimeException('Upload a PNG, JPG or WebP image.');
    $logo='uploads/'.bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($_FILES['logo']['tmp_name'],__DIR__.'/'.$logo))throw new RuntimeException('Logo upload failed. Check uploads folder permissions.');
   }
   $q=db()->prepare('INSERT INTO settings(name,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)');foreach(['store_name'=>$store,'primary_color'=>$color,'logo_path'=>$logo] as $k=>$v)$q->execute([$k,$v]);flash('Appearance saved.');redirect('settings');
  }
  if($action==='add_user'){
   require_admin();$name=trim((string)($_POST['name']??''));$username=strtolower(trim((string)($_POST['username']??'')));$pass=(string)($_POST['password']??'');$role=(string)($_POST['role']??'cashier');
   if(!$name||!preg_match('/^[a-z0-9_.-]{3,40}$/',$username)||strlen($pass)<6||!in_array($role,['admin','cashier'],true))throw new RuntimeException('Use a username (3–40 letters, numbers, dots, underscores or hyphens) and password of at least 6 characters.');
   $q=db()->prepare('INSERT INTO users(name,username,password_hash,role) VALUES(?,?,?,?)');$q->execute([$name,$username,password_hash($pass,PASSWORD_DEFAULT),$role]);flash('Staff account created.');redirect('users');
  }
  throw new RuntimeException('Unknown action.');
 }
} catch(Throwable $ex){$error=$ex instanceof PDOException?'Database operation failed. Check for duplicate SKU or username.':$ex->getMessage();}
if($page==='login'){
 if(isset($_SESSION['user']))redirect('dashboard');
