<?php elseif($page==='settings'):?><div class="panel settings-panel"><h2>Store appearance</h2><p class="muted">Your logo and theme color update the POS interface.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="save_settings"><label>Store name<input name="store_name" required maxlength="100" value="<?=e($store)?>"></label><label>Theme color<input type="color" name="primary_color" value="<?=e($primary)?>"></label><label>Store logo (PNG / JPG / WebP, up to 2 MB)<input type="file" name="logo" accept="image/png,image/jpeg,image/webp"></label><?php if($logo):?><img class="logo-preview" src="<?=e($logo)?>" alt="Current store logo"><?php endif;?><button class="primary" type="submit">Save appearance</button></form></div>
<?php elseif($page==='users'):$users=db()->query('SELECT id,name,username,role,created_at FROM users ORDER BY id')->fetchAll();?><div class="staff-layout"><div class="panel staff-form"><h2>Add staff user</h2><p class="muted">Create an admin or cashier account.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="add_user"><label>Name<input name="name" required maxlength="100"></label><label>Username<input name="username" required minlength="3" maxlength="40" pattern="[A-Za-z0-9_.-]+"></label><label>Password (at least 6 characters)<input name="password" type="password" minlength="6" required></label><label>Role<select name="role"><option value="cashier">Cashier</option><option value="admin">Admin</option></select></label><button class="primary" type="submit">Add staff user</button></form></div><div class="panel table-wrap"><h2>Staff accounts</h2><table><thead><tr><th>Name</th><th>Username</th><th>Role</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=e($u['name'])?></td><td><?=e($u['username'])?></td><td><?=e(ucfirst($u['role']))?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php endif;?></main></div></body></html>
